package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.NoSuchElementException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BeanPropertyMap_remove_TriageGen1Test {

    private SettableBeanProperty prop1;
    private SettableBeanProperty prop2;
    private SettableBeanProperty prop3;

    @Before
    public void setUp() {
        prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");

        prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("prop2");

        prop3 = mock(SettableBeanProperty.class);
        when(prop3.getName()).thenReturn("prop3");
    }

    @Test
    public void testRemove_Success_MiddleElement() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2, prop3));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        map.remove(prop2);

        assertEquals(2, map.size());
        assertNull(map.find("prop2"));
        assertNotNull(map.find("prop1"));
        assertNotNull(map.find("prop3"));
    }

    @Test
    public void testRemove_Success_FirstElement() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        map.remove(prop1);

        assertEquals(1, map.size());
        assertNull(map.find("prop1"));
        assertNotNull(map.find("prop2"));
    }

    @Test
    public void testRemove_Success_LastElement() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        map.remove(prop2);

        assertEquals(1, map.size());
        assertNull(map.find("prop2"));
        assertNotNull(map.find("prop1"));
    }

    @Test(expected = NoSuchElementException.class)
    public void testRemove_NotFound_ThrowsException() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        // prop3 is not in the map
        map.remove(prop3);
    }

    @Test
    public void testRemove_WithNullInHashArea() {
        // This test targets the 'if (prop == null) continue;' branch
        // Since we use construct(), we need to simulate a state where the internal array has nulls
        // However, BeanPropertyMap internals are encapsulated. 
        // We will test via a construction that might result in sparse arrays if implementation allows,
        // but usually, construct() fills it. 
        // To force the 'prop == null' branch, we rely on the fact that the loop skips even indices 
        // and checks i=1, 3, 5...

        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        // The loop in remove iterates i=1, 3, 5... 
        // If the internal _hashArea is large enough and has nulls at odd indices, it hits the branch.
        // Given the provided code, we can't easily inject a null into _hashArea without reflection.
        // Using reflection to ensure coverage of the 'if (prop == null)' branch.

        try {
            java.lang.reflect.Field hashAreaField = BeanPropertyMap.class.getDeclaredField("_hashArea");
            hashAreaField.setAccessible(true);
            Object[] hashArea = (Object[]) hashAreaField.get(map);

            // Find an odd index that is currently occupied and set it to null
            for (int i = 1; i < hashArea.length; i += 2) {
                if (hashArea[i] != null) {
                    hashArea[i] = null;
                    break;
                }
            }

            // Now remove a property that exists. The loop will encounter the null and 'continue'.
            map.remove(prop2);
            assertEquals(1, map.size());
            assertNotNull(map.find("prop1"));
        } catch (Exception e) {
            // If reflection fails in certain environments, the test is skipped, 
            // but in a standard JUnit environment, this covers the branch.
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testRemove_CaseInsensitiveMatch() {
        // Testing the comment: "must check name slot and NOT property name"
        // We create a scenario where the name is the same but case sensitivity matters.
        SettableBeanProperty propUpper = mock(SettableBeanProperty.class);
        when(propUpper.getName()).thenReturn("PROP1");

        SettableBeanProperty propLower = mock(SettableBeanProperty.class);
        when(propLower.getName()).thenReturn("prop1");

        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(propUpper, propLower));
        // caseInsensitive = true
        BeanPropertyMap map = BeanPropertyMap.construct(props, true);

        // Removing "prop1" should find "PROP1" or "prop1" depending on getPropertyName logic
        // In Jackson, getPropertyName usually returns the name.
        map.remove(propLower);

        // Verify that one was removed. 
        // Since the loop uses key.equals(prop.getName()), and we are in case-insensitive mode,
        // the behavior depends on getPropertyName implementation.
        assertTrue(map.size() < 2);
    }
}
